import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2, mul, add } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Create root group
  const root = new Group();

  // Geometry sized to atlas region aspect ratio (512:320 = 1.6)
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // Node material with texture node
  const texNode = texture(); // placeholder node, texture assigned later
  const material = new MeshBasicNodeMaterial();
  material.map = texNode;

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously, assign to node when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texNode.value = tex;
      material.needsUpdate = true;
    });
  }

  // Billboard handler (rotate plane to face camera each render)
  root.userData.handlers = {
    render: (renderer, scene, camera) => {
      mesh.lookAt(camera.position);
    },
  };

  // Cleanup resources
  root.userData.cleanup = () => {
    // No GSAP timelines used, but kill any if added later
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();
    // texNode will be garbage‑collected; texture is cached by ctx
  };

  return root;
}
